    for _ in range(50):
        improved = False
        for i in range(n - 1):
            for j in range(i + 2, n):
                # 2-opt: reverse segment [i+1, j]
                result[i+1:j+1] = result[i+1:j+1][::-1]
                new_cost = ctx.evaluate(result)
                if new_cost < current_cost:
                    current_cost = new_cost
                    improved = True
                    break
                result[i+1:j+1] = result[i+1:j+1][::-1]  # Undo
            if improved:
                break
        if not improved:
