def ls_chain(solution, ctx):
    """Chain: first-improvement swaps then 2-opt."""
    result = solution[:]
    n = len(result)
    # Phase 1: First-improvement swaps
    current_cost = ctx.evaluate(result)
    for i in range(n):
        for j in range(i + 1, n):
            result[i], result[j] = result[j], result[i]
            new_cost = ctx.evaluate(result)
            if new_cost < current_cost:
                current_cost = new_cost
            else:
                result[i], result[j] = result[j], result[i]  # Undo
    # Phase 2: 2-opt
    for i in range(n - 1):
        for j in range(i + 2, n):
            result[i+1:j+1] = result[i+1:j+1][::-1]
            new_cost = ctx.evaluate(result)
            if new_cost < current_cost:
                current_cost = new_cost
            else:
                result[i+1:j+1] = result[i+1:j+1][::-1]  # Undo
    return result

def ls_chain_adaptive_lkh_3b87f4(s, ctx):
    """Adaptive, history-driven local search chain for TSP.

    Operator set (improving-only, first-improvement):
      - 2-opt (edge exchange)
      - relocate (Or-opt 1) (remove a city and reinsert elsewhere)
      - swap (exchange two cities)

    Candidate sets: use k-nearest neighbor positions for each i.
    Adaptive selection: prefer operators that recently succeeded.
    History-driven: avoid immediately undoing the last move and track recently touched indices.

    Requires ctx.delta(s, move, i, j) with move in {'2opt','relocate','swap'}.
    """
    import random

    n = len(s)
    if n < 4:
        return s

    # --- Tunables (kept small for speed at n≈100) ---
    k = min(20, n - 1)          # candidate list size
    max_iter = 25 * n           # hard cap on attempted improvements
    eps = 1e-9

    # Adaptive weights for operator choice
    ops = ['2opt', 'relocate', 'swap']
    w = {'2opt': 3.0, 'relocate': 2.0, 'swap': 1.0}

    # History: recently modified indices (positions), and last move to avoid trivial backtracks
    tabu_window = max(10, n // 10)
    recent = []  # list of positions recently affected
    last_move = None  # tuple(op,i,j)

    def touch(pos_list):
        for p in pos_list:
            recent.append(p)
        # truncate
        if len(recent) > tabu_window:
            del recent[:len(recent) - tabu_window]

    def is_recent(p):
        # small window, linear scan is fine
        for x in recent:
            if x == p:
                return True
        return False

    def weighted_choice(items, weights_dict):
        total = 0.0
        for it in items:
            total += weights_dict[it]
        r = random.random() * total
        acc = 0.0
        for it in items:
            acc += weights_dict[it]
            if r <= acc:
                return it
        return items[-1]

    # Cache neighbor lists per position lazily each iteration sweep.
    # Note: ctx.neighbors(s, i, k) returns positions (not node ids).
    neighbor_cache = [None] * n

    def get_neighbors(i):
        nb = neighbor_cache[i]
        if nb is None:
            nb = ctx.neighbors(s, i, k)
            # ensure list and filter bounds/self
            nb2 = []
            for j in nb:
                if 0 <= j < n and j != i:
                    nb2.append(j)
            neighbor_cache[i] = nb2
            return nb2
        return nb

    def apply_move(op, i, j):
        if op == '2opt':
            if i > j:
                i, j = j, i
            if j <= i + 1:
                return
            s[i + 1:j + 1] = s[i + 1:j + 1][::-1]
        elif op == 'swap':
            s[i], s[j] = s[j], s[i]
        elif op == 'relocate':
            # Remove position i, insert at position j (after removal indexing)
            if i == j:
                return
            node = s.pop(i)
            if j > i:
                j -= 1
            s.insert(j, node)
        else:
            return

    # Main loop: first-improvement with adaptive operator selection
    it = 0
    while it < max_iter:
        it += 1

        # refresh neighbor cache periodically because tour changes
        if it % n == 1:
            neighbor_cache = [None] * n

        op = weighted_choice(ops, w)

        # Choose a pivot position; bias away from very recent positions to diversify
        if n <= 2:
            break
        for _ in range(5):
            i = random.randrange(n)
            if not is_recent(i):
                break
        else:
            i = random.randrange(n)

        candidates = get_neighbors(i)
        if not candidates:
            continue

        # Shuffle a small prefix to keep first-improvement behavior but avoid determinism
        # (full shuffle is small anyway at k<=20)
        random.shuffle(candidates)

        improved = False
        for j in candidates:
            if i == j:
                continue

            # Avoid immediate backtrack of the last accepted move
            if last_move is not None and last_move[0] == op:
                li, lj = last_move[1], last_move[2]
                if (i == li and j == lj) or (i == lj and j == li):
                    continue

            # Basic feasibility pruning for 2-opt
            if op == '2opt':
                a, b = (i, j) if i < j else (j, i)
                if b <= a + 1:
                    continue

            d = ctx.delta(s, op, i, j)
            if d < -eps:
                apply_move(op, i, j)

                # Update history
                if op == '2opt':
                    a, b = (i, j) if i < j else (j, i)
                    touch([a, a + 1, b, b + 1 if b + 1 < n else 0])
                elif op == 'swap':
                    touch([i, j])
                else:  # relocate
                    touch([i, j])

                last_move = (op, i, j)

                # Reward the operator that worked; mild decay for others
                w[op] = min(10.0, w[op] + 0.5)
                for other in ops:
                    if other != op:
                        w[other] = max(0.5, w[other] * 0.98)

                improved = True
                break

        if improved:
            # First-improvement: return immediately after one improving move
            return s
        else:
            # No improvement found around pivot with chosen op: slight penalty
            w[op] = max(0.5, w[op] * 0.95)

    return s

