def pert_escape_small_hist_point_tourn_metropolis_a65e55(s, ctx):
    """History-driven point perturbation with tournament selection + Metropolis acceptance.

    Well-known building blocks from TSP/ILS literature:
    - Or-opt(1) (single-node relocation) and 2-swap as *point-scope* kicks
    - (optional) nearest-neighbor bias for candidate target selection
    - tournament among k candidates using O(1) delta evaluation
    - probabilistic (SA/Metropolis) acceptance to allow worse moves for escape
    - history-driven diversification via a small tabu-like memory of recently moved nodes

    Fast: O(k) ctx.delta calls, O(n) once to apply the selected move.
    """
    import random
    import math

    n = len(s)
    if n < 4:
        return s[:]

    # Very small instances: just do a couple random swaps
    if n < 8:
        res = s[:]
        for _ in range(random.randint(2, 3)):
            i, j = random.sample(range(n), 2)
            res[i], res[j] = res[j], res[i]
        return res

    # ---- history (tabu-like) memory of recently moved *nodes* (values) ----
    # Stored on ctx to drive diversification.
    mem = getattr(ctx, "_pert_hist", None)
    if mem is None:
        mem = {
            "recent": [],
            "cap": max(12, min(40, n // 3))
        }
        try:
            setattr(ctx, "_pert_hist", mem)
        except Exception:
            pass

    recent = mem.get("recent", [])
    recent_set = set(recent)
    cap = int(mem.get("cap", max(12, min(40, n // 3))))

    # ---- effort and temperature ----
    stag = 0
    for key in ("stagnation", "no_improve", "iters_no_improve", "plateau"):
        if hasattr(ctx, key):
            try:
                stag = int(getattr(ctx, key) or 0)
            except Exception:
                stag = 0
            break

    # Tournament size: small but adaptive
    k = 6 + min(6, max(0, stag // 25))  # 6..12

    # Temperature (small): scale with n, slightly higher under stagnation
    T = (0.0015 * n) * (1.0 + min(1.5, stag / 200.0))
    T = max(1e-9, T)

    have_neighbors = hasattr(ctx, "neighbors")

    # Candidate move generator (point-scope): Or-opt(1) or swap
    # We score candidates by delta + history penalty (prefer moving "fresh" nodes).
    best = None  # (score, delta, move, i, j, touched_nodes)

    def pick_i():
        # Prefer positions whose node hasn't been moved recently
        if recent and random.random() < 0.75:
            for _ in range(6):
                i0 = random.randrange(n)
                if s[i0] not in recent_set:
                    return i0
        return random.randrange(n)

    def pick_j(i):
        # Mix NN-guided targets and far targets to create an escape
        if have_neighbors and random.random() < 0.55:
            try:
                nn = ctx.neighbors(s, i, 10)
            except Exception:
                nn = []
            if nn:
                j0 = random.choice(list(nn))
                if random.random() < 0.30:
                    j0 = (j0 + random.choice([-2, -1, 1, 2])) % n
                if j0 == i:
                    j0 = (j0 + 1) % n
                return j0

        # Far index (distributed change)
        step = random.randint(max(2, n // 8), max(3, n // 2))
        j0 = (i + step) % n
        if j0 == i:
            j0 = (j0 + 1) % n
        return j0

    for _ in range(k):
        i = pick_i()
        j = pick_j(i)
        if i == j:
            continue

        move = "ins" if random.random() < 0.65 else "swap"

        # Avoid near-no-op insertions
        if move == "ins":
            if j == i or j == (i + 1) % n:
                move = "swap"

        try:
            d = ctx.delta(s, move, i, j)
        except Exception:
            # If delta not available, fall back to a cheap random point move
            d = None

        if d is None:
            continue

        # History penalty: discourage touching recently moved nodes
        if move == "swap":
            touched = (s[i], s[j])
        else:
            touched = (s[i],)

        penalty = 0.0
        # Penalize if any touched node is in the recent list
        for node in touched:
            if node in recent_set:
                penalty += 0.25 * T  # small relative penalty, scaled with T

        score = d + penalty

        if best is None or score < best[0]:
            best = (score, d, move, i, j, touched)

    # If we couldn't score anything (no delta), do a simple, valid point perturbation
    if best is None:
        res = s[:]
        if random.random() < 0.6:
            i, j = random.sample(range(n), 2)
            node = res.pop(i)
            if j > i:
                j -= 1
            res.insert(j, node)
        else:
            i, j = random.sample(range(n), 2)
            res[i], res[j] = res[j], res[i]
        return res

    _, d_best, move, i_best, j_best, touched_best = best

    # Metropolis acceptance based on delta (history penalty only affects selection)
    if d_best <= 0:
        accept = True
    else:
        accept = (random.random() < math.exp(-d_best / T))

    if not accept:
        # Ensure some escape anyway: apply a single random Or-opt(1) kick
        res = s[:]
        i = random.randrange(n)
        j = (i + random.randint(max(2, n // 6), max(3, n // 2))) % n
        node = res.pop(i)
        if j > i:
            j -= 1
        res.insert(j, node)
        # Update history best-effort
        try:
            recent.append(node)
            if len(recent) > cap:
                del recent[:len(recent) - cap]
            mem["recent"] = recent
        except Exception:
            pass
        return res

    # Apply selected point move
    res = s[:]
    if move == "swap":
        res[i_best], res[j_best] = res[j_best], res[i_best]
    else:
        node = res.pop(i_best)
        j2 = j_best
        if j2 > i_best:
            j2 -= 1
        res.insert(j2, node)

    # Update history best-effort
    try:
        for node in touched_best:
            recent.append(node)
        if len(recent) > cap:
            del recent[:len(recent) - cap]
        mem["recent"] = recent
    except Exception:
        pass

    return res
